def F(x, a1, a2):
    P = 10 <= x <= 15
    Q = 10 <= x <= 20
    R = 5 <= x <= 15
    A = a1 <= x <= a2
    return (A <= P) == (Q <= R)


R = []
M = [x / 4 for x in range(5 * 4, 20 * 4)]
for a1 in M:
    for a2 in M:
        if all(F(x, a1, a2) for x in M):
            R.append(a2 - a1)

print(min(R))
